import { Button } from '@refy-design/web';
import { Checkbox } from '@refy-design/web';
import { Popover } from '@refy-design/web';
import { useState } from 'react';
const stack = { display: 'grid', gap: 'var(--space-4)', minWidth: 0 } as const;
function PopoverExample() {
  const [open, setOpen] = useState(false),
    [draft, setDraft] = useState(false),
    [onlyApproved, setOnlyApproved] = useState(false);
  const rows = [
    { name: 'Content guide', approved: true },
    { name: 'Visual references', approved: false },
  ];
  return (
    <div style={stack}>
      <Popover
        open={open}
        onOpenChange={setOpen}
        label="Filters"
        content={
          <div style={stack}>
            <Checkbox
              label="Approved only"
              checked={draft}
              onChange={(e) => setDraft(e.target.checked)}
            />
            <Button
              onClick={() => {
                setOnlyApproved(draft);
                setOpen(false);
              }}
            >
              Apply filters
            </Button>
          </div>
        }
      >
        <Button
          onClick={() => {
            setDraft(onlyApproved);
            setOpen(!open);
          }}
        >
          Filter
        </Button>
      </Popover>
      <ul>
        {rows
          .filter((row) => !onlyApproved || row.approved)
          .map((row) => (
            <li key={row.name}>
              {row.name} · {row.approved ? 'Approved' : 'In review'}
            </li>
          ))}
      </ul>
    </div>
  );
}
export function Example() {
  return <PopoverExample />;
}
